    gh = observation.get("grid_height", 0) if hasattr(observation, "get") else 0

    def _step_toward(tx, ty):
        return [_clamp_step(tx - sx), _clamp_step(ty - sy)]

    def _step_away(tx, ty):
        return [_clamp_step(sx - tx), _clamp_step(sy - ty)]

    if env == "pursuit_evasion":
