            opp = _pos(observation.get("opponent_position") if hasattr(observation, "get") else None, (sx, sy))
            return _step_toward(opp[0], opp[1])
        best = min(candidates, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
        return _step_toward(best[0], best[1])

    resources = []
    for key in ("resources", "resource_positions", "resource_cells", "targets"):
        resources = _get_positions(observation.get(key) if hasattr(observation, "get") else None)
        if resources:
            break

    if resources:
        best = min(resources, key=lambda p: abs(p[0] - sx) + abs(p[1] - sy))
        return _step_toward(best[0], best[1])

    # fallback: be somewhat evasive if close, otherwise drift toward opponent
    if abs(ox - sx) + abs(oy - sy) <= 2:
        return _step_away(ox, oy)
    return _step_toward(ox, oy)

